mapper.select:
SELECT t.tender_id,
       t.tender_code,
       t.tender_name,
       t.tender_type,
       t.tender_mode,
       t.company_id AS purchaser_id,
       t.budget_amount,
       t.currency,
       t.bid_start_time,
       t.bid_end_time,
       t.status,
       t.project_id,
       t.created_by,
       t.created_time
FROM exp_tender t


        AND t.tender_code LIKE CONCAT('%', #{req.tenderCode}, '%')


        AND t.tender_name LIKE CONCAT('%', #{req.tenderName}, '%')


        AND t.tender_type = #{req.tenderType}


        AND t.tender_mode = #{req.tenderMode}


        AND t.company_id = #{req.purchaserId}


        AND t.status = #{req.status}


        AND t.project_id = #{req.projectId}


        AND t.created_by = #{req.createdBy}


        AND t.bid_start_time >= #{req.bidStartTimeStart}


        AND t.bid_start_time <= #{req.bidStartTimeEnd}


        AND t.bid_end_time >= #{req.bidEndTimeStart}


        AND t.bid_end_time <= #{req.bidEndTimeEnd}


ORDER BY t.created_time DESC

SELECT COUNT(1)
FROM exp_tender
WHERE tender_code = #{tenderCode}

    AND tender_id != #{excludeTenderId}
